def seed_pilot(apps,schema_editor):
    Batch=apps.get_model('contacts','ImportBatch');Merchant=apps.get_model('contacts','KaspiMerchant');Client=apps.get_model('contacts','Client')
    batch=Batch.objects.filter(result__kind='kaspi_pilot').order_by('-committed_at').first()
    if not batch:return
    for row in batch.rows:
        client=Client.objects.filter(identity_key='kaspi:merchant:'+row['merchant_id']).first()
        codes=[code for code,name in [('cpus','Процессоры'),('desktops','Системные блоки')] if name in row['categories']]
        Merchant.objects.get_or_create(merchant_id=row['merchant_id'],defaults={'name':row['shop_name'],
            'city':row['city'],'addresses':row['addresses'],'phones':row['phones'],'category_codes':codes,
            'source_urls':row['discovery_urls'],'client_id':client.pk if client else None,'checked_at':batch.committed_at})


